import os, re, subprocess

result = subprocess.run\(['find', '.', '-name', '*.tsx', '-o', '-name', '*.ts'], capture_output=True, text=True\)
files = result.stdout.strip\(\).split\('\\n'\)

mismatches = set\(\)

for f in files:
    if not f: continue
    try:
        content = open\(f\).read\(\)
    except: continue

    for m in re.finditer\(r"""from\\s+['"]\(@/[^'"]+|\\.\\.?/[^'"]+\)['"]""", content\):
        imp = m.group\(1\)

        if imp.startswith\('@/'\):
            resolved = imp[2:]
        else:
            resolved = os.path.normpath\(os.path.join\(os.path.dirname\(f\), imp\)\)

        parts = resolved.split\('/'\)
        current = '.'
        for part in parts:
            if not os.path.isdir\(current\):
                break
            try:
                entries = os.listdir\(current\)
            except:
                break
            for e in entries:
                base_e = e
                for ext in ['', '.ts', '.tsx', '.js', '.jsx']:
                    if ext and e == part + ext:
                        break
                if e.lower\(\) == part.lower\(\) and e != part:
                    key = \(f, imp, os.path.join\(current, part\), os.path.join\(current, e\)\)
                    mismatches.add\(key\)
            current = os.path.join\(current, part\)

for f, imp, expected, actual in sorted\(mismatches\):
    print\(f"FILE: {f}"\)
    print\(f"  IMPORT: {imp}"\)
    print\(f"  Import uses:  {os.path.basename\(expected\)}"\)
    print\(f"  Actual on disk: {os.path.basename\(actual\)}"\)
    print\(\)
